import React from 'react';
import { ItemProbabilityBar } from '../ItemProbabilityBar';
import { TrashIcon, CheckCircleIcon } from '../Icons';
import { useI18n } from '../../i18n';
import { NodeEffectivePool } from './NodeEffectivePool';
import { ScumJson } from '../../types';
import { hasTranslation, getItemTranslation } from '../../utils/itemTranslator';

interface NodesSectionProps {
    nodes: any[];
    isBulkMode: boolean;
    selectedIndices: Set<number>;
    onSelect: (index: number) => void;
    handleContainerDrop: (e: React.DragEvent, section: any) => void;
    deleteItem: (section: any, index: number) => void;
    updateItem: (section: any, index: number, field: string, value: any) => void;
    filterList: (list: any[]) => { item: any; originalIndex: number }[];
    getGlobalPercentage: (id: string | undefined, rarity: string, section: any) => string;
    combinedLootStats: any;
    onItemClick: (id: string) => void;
    onHoverItem: (id: string | null) => void;
    hoveredItemId: string | null;
    getInputClass: (key?: string) => string;
    currentLibrary: any;
    handleLibraryDropOnNode: (e: React.DragEvent, index: number) => void;
    nodeOverrides?: Record<string, ScumJson>;
}

const RARITY_OPTIONS = ["Abundant", "Common", "Uncommon", "Rare", "VeryRare", "ExtremelyRare"];

export const NodesSection: React.FC<NodesSectionProps> = ({
    nodes,
    isBulkMode,
    selectedIndices,
    onSelect,
    handleContainerDrop,
    deleteItem,
    updateItem,
    filterList,
    getGlobalPercentage,
    combinedLootStats,
    onItemClick,
    onHoverItem,
    hoveredItemId,
    getInputClass,
    currentLibrary,
    handleLibraryDropOnNode,
    nodeOverrides
}) => {
    const { t } = useI18n();

    return (
        <div>
            <div className="flex flex-col gap-2 relative">
                <ItemProbabilityBar 
                    items={nodes} 
                    type="Node" 
                    onItemClick={onItemClick} 
                    onHoverItem={onHoverItem} 
                    hoveredId={hoveredItemId} 
                    customStats={combinedLootStats} 
                />
            </div>

            <div className="grid gap-6 min-h-[100px]" onDragOver={(e) => e.preventDefault()} onDrop={(e) => handleContainerDrop(e, 'Nodes')}>
                {filterList(nodes).map(({ item: node, originalIndex: idx }) => {
                    const firstId = node.Ids && node.Ids.length > 0 ? node.Ids[0] : null; 
                    const nodeId = firstId ? `Node [${firstId}]` : `Node #${idx+1}`; 
                    const isHovered = nodeId === hoveredItemId;
                    const isSelected = selectedIndices.has(idx);

                    return (
                    <div 
                        key={idx} 
                        data-scum-item-id={nodeId} 
                        className={`
                            relative p-6 rounded-2xl border transition-all duration-300 group focus-within:z-50
                            ${isSelected ? 'bg-scum-800/80 border-pink-500/50 ring-1 ring-pink-500/30' : 'bg-scum-800/40 border-scum-700/50 hover:bg-scum-800/60'}
                            ${isHovered ? 'ring-2 ring-pink-400' : ''}
                        `} 
                        onDrop={(e) => handleLibraryDropOnNode(e, idx)}
                    >
                        <div className="flex items-center justify-between mb-4">
                            <div className="flex items-center gap-4">
                                {isBulkMode ? (
                                    <div 
                                        className={`w-5 h-5 rounded border cursor-pointer flex items-center justify-center transition-colors ${isSelected ? 'bg-pink-500 border-pink-500' : 'border-gray-600 hover:border-gray-400'}`}
                                        onClick={() => onSelect(idx)}
                                    >
                                        {isSelected && <CheckCircleIcon className="w-3.5 h-3.5 text-black" />}
                                    </div>
                                ) : (
                                    <div className="text-sm font-bold text-gray-500">#{idx + 1}</div>
                                )}

                                <div className="flex flex-col">
                                    <div className="flex items-center gap-2">
                                        <select className={`${getInputClass(`nodes_${idx}_rarity`)} w-40 font-bold text-pink-300`} value={node.Rarity} onChange={(e) => updateItem('Nodes', idx, 'Rarity', e.target.value)}>{RARITY_OPTIONS.map(r => <option key={r} value={r}>{t(`rarity.${r}`)}</option>)}</select>
                                        <span className="text-[10px] text-gray-500 font-mono w-12 text-right mt-4">{getGlobalPercentage(undefined, node.Rarity, 'Nodes')}</span>
                                    </div>
                                </div>
                            </div>
                            <button onClick={() => deleteItem('Nodes', idx)} className="p-2 text-gray-500 hover:text-scum-danger"><TrashIcon /></button>
                        </div>
                        <div className="bg-black/20 rounded-lg p-3 border border-white/5 min-h-[50px] mb-3">
                            <div className="flex flex-col gap-1.5 items-start max-h-48 overflow-y-auto custom-scrollbar pr-1 w-full">
                                {node.Ids?.map((id: string, idIdx: number) => {
                                    const hasTrans = hasTranslation(id);
                                    const translation = hasTrans ? getItemTranslation(id) : null;

                                    return (
                                        <div key={idIdx} className="group/tag flex items-center bg-scum-900 border rounded px-2 py-1 text-xs border-scum-700">
                                            {hasTrans ? (
                                                <div className="flex flex-col">
                                                    <span className="text-sky-300 font-bold leading-tight">{translation}</span>
                                                    <span className="text-[9px] text-gray-600 font-mono leading-tight">{id}</span>
                                                </div>
                                            ) : (
                                                <span className="text-gray-300 font-mono font-bold">{id}</span>
                                            )}
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                        <NodeEffectivePool nodeIds={node.Ids} library={currentLibrary} nodeOverrides={nodeOverrides} />
                    </div>
                    );
                })}
            </div>
        </div>
    );
};

import React from 'react';
import { TrashIcon, EyeIcon, CheckCircleIcon } from '../Icons'; 
import { useI18n } from '../../i18n';

interface ZonesSectionProps {
    zones: any[];
    handleContainerDrop: (e: React.DragEvent, section: any) => void;
    deleteItem: (section: any, index: number) => void;
    updateItem: (section: any, index: number, field: string, value: any) => void;
    getInputClass: (key?: string) => string;
    onPickZone?: (index: number) => void;
    isBulkMode?: boolean;
    selectedIndices?: Set<number>;
    onSelect?: (index: number) => void;
}

export const ZonesSection: React.FC<ZonesSectionProps> = ({
    zones,
    handleContainerDrop,
    deleteItem,
    updateItem,
    getInputClass,
    onPickZone,
    isBulkMode,
    selectedIndices,
    onSelect
}) => {
    const { t } = useI18n();

    return (
        <div className="space-y-3 min-h-[100px]" onDragOver={(e) => e.preventDefault()} onDrop={(e) => handleContainerDrop(e, 'Zones')}>
            {(zones || []).map((zone, idx) => {
                const isSelected = selectedIndices?.has(idx);
                return (
                <div 
                    key={idx} 
                    className={`
                        relative p-4 rounded-lg flex items-center gap-4 border transition-all focus-within:z-50
                        ${isSelected ? 'bg-scum-800/80 border-yellow-500/50 ring-1 ring-yellow-500/30' : 'bg-scum-800/30 border-scum-700/50 hover:bg-scum-800/60'}
                    `} 
                    data-scum-item-id={'Zone #' + idx}
                >
                    {isBulkMode && onSelect ? (
                        <div 
                            className={`w-5 h-5 rounded border cursor-pointer flex items-center justify-center transition-colors ${isSelected ? 'bg-yellow-500 border-yellow-500' : 'border-gray-600 hover:border-gray-400'}`}
                            onClick={() => onSelect(idx)}
                        >
                            {isSelected && <CheckCircleIcon className="w-3.5 h-3.5 text-black" />}
                        </div>
                    ) : (
                        <div className="text-[10px] font-mono text-gray-600 w-6">#{idx+1}</div>
                    )}

                    <div className="grid grid-cols-2 gap-4 flex-1">
                        <div><label className="text-[10px] uppercase text-gray-500 font-bold mb-1 block">{t('common.topLeft')}</label><input className={`${getInputClass()} font-mono text-xs`} value={zone.TopLeft} onChange={e => updateItem('Zones', idx, 'TopLeft', e.target.value)} /></div>
                        <div><label className="text-[10px] uppercase text-gray-500 font-bold mb-1 block">{t('common.bottomRight')}</label><input className={`${getInputClass()} font-mono text-xs`} value={zone.BottomRight} onChange={e => updateItem('Zones', idx, 'BottomRight', e.target.value)} /></div>
                    </div>
                    {onPickZone && (
                        <button 
                            onClick={() => onPickZone(idx)} 
                            className="p-2 bg-black/20 hover:bg-scum-accent/20 text-scum-accent border border-scum-accent/30 rounded-lg transition-all"
                            title={t('zone.pickFromMap')}
                        >
                            <EyeIcon className="w-4 h-4" />
                        </button>
                    )}
                    <button onClick={() => deleteItem('Zones', idx)} className="p-2 text-gray-600 hover:text-scum-danger"><TrashIcon /></button>
                </div>
            )})}
        </div>
    );
};

import React from 'react';
import { ScumJson, POST_SPAWN_ACTIONS } from '../../types';
import { useI18n } from '../../i18n';
import { BooleanToggle } from '../../components/FormControls';
import { PlusIcon, TrashIcon, CheckCircleIcon } from '../Icons';

interface GlobalSectionProps {
    data: ScumJson;
    updateGlobal: (field: keyof ScumJson, value: any) => void;
    deleteItem: (section: any, index: number) => void;
    addItem: (section: any) => void;
    updateStringItem: (section: any, index: number, value: string) => void;
    getInputClass: (errorKey?: string) => string;
    isBulkMode?: boolean;
    selectedGroups?: Set<string>;
    onToggleGroup?: (group: string) => void;
}

export const GlobalSection: React.FC<GlobalSectionProps> = ({ 
    data, 
    updateGlobal, 
    deleteItem, 
    addItem, 
    updateStringItem,
    getInputClass,
    isBulkMode,
    selectedGroups,
    onToggleGroup
}) => {
    const { t } = useI18n();

    const renderBulkCheckbox = (group: string) => {
        if (!isBulkMode || !onToggleGroup || !selectedGroups) return null;
        const isSelected = selectedGroups.has(group);
        return (
            <div 
                onClick={() => onToggleGroup(group)}
                className={`w-6 h-6 rounded border flex items-center justify-center cursor-pointer transition-all ${isSelected ? 'bg-scum-accent border-scum-accent shadow-[0_0_10px_rgba(6,182,212,0.4)]' : 'bg-black/20 border-gray-600 hover:border-gray-400'}`}
            >
                {isSelected && <CheckCircleIcon className="w-4 h-4 text-black" />}
            </div>
        );
    };

    return (
        <div className="space-y-6 pb-20">
            {/* Generation Control */}
            <div className={`space-y-4 bg-scum-800/40 p-6 rounded-2xl border transition-all ${isBulkMode && selectedGroups?.has('gen') ? 'border-scum-accent ring-1 ring-scum-accent/30 bg-scum-800/60' : 'border-scum-accent/50'}`}>
                 <div className="flex justify-between items-center border-b border-scum-700/50 pb-2 mb-4">
                     <h4 className="text-xs font-bold text-scum-accent uppercase tracking-wider flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-scum-accent animate-pulse"></span>{t('global.genControl')}</h4>
                     {renderBulkCheckbox('gen')}
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.minQty')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.QuantityMin ?? ""} onChange={e => updateGlobal('QuantityMin', parseFloat(e.target.value))} /></div>
                    <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.maxQty')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.QuantityMax ?? ""} onChange={e => updateGlobal('QuantityMax', parseFloat(e.target.value))} /></div>
                    <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.prob')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.Probability ?? ""} onChange={e => updateGlobal('Probability', parseFloat(e.target.value))} /></div>
                 </div>
            </div>

            {/* Flags / Rules */}
            <div className={`bg-scum-800/40 p-6 rounded-2xl border transition-all ${isBulkMode && selectedGroups?.has('flags') ? 'border-purple-500 ring-1 ring-purple-500/30 bg-scum-800/60' : 'border-purple-500/50'}`}>
                <div className="flex justify-between items-center border-b border-scum-700/50 pb-2 mb-4">
                    <h4 className="text-xs font-bold text-purple-400 uppercase tracking-wider flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-purple-500 animate-pulse"></span>{t('global.flags')}</h4>
                    {renderBulkCheckbox('flags')}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <BooleanToggle label={t('global.allowDuplicates')} value={data.AllowDuplicates} onChange={v => updateGlobal('AllowDuplicates', v)} color="fuchsia" />
                    <BooleanToggle label={t('global.filterByZone')} value={data.ShouldFilterItemsByZone} onChange={v => updateGlobal('ShouldFilterItemsByZone', v)} color="fuchsia" />
                    <BooleanToggle label={t('global.probMod')} value={data.ShouldApplyLocationSpecificProbabilityModifier} onChange={v => updateGlobal('ShouldApplyLocationSpecificProbabilityModifier', v)} color="fuchsia" />
                    <BooleanToggle label={t('global.damageMod')} value={data.ShouldApplyLocationSpecificDamageModifier} onChange={v => updateGlobal('ShouldApplyLocationSpecificDamageModifier', v)} color="fuchsia" />
                </div>
            </div>

            {/* Item State (Damage/Usage) */}
            <div className={`bg-scum-800/40 p-6 rounded-2xl border transition-all ${isBulkMode && selectedGroups?.has('damage') ? 'border-orange-500 ring-1 ring-orange-500/30 bg-scum-800/60' : 'border-orange-500/50'}`}>
                <div className="flex justify-between items-center border-b border-scum-700/50 pb-2 mb-4">
                    <h4 className="text-xs font-bold text-orange-400 uppercase tracking-wider flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-orange-500 animate-pulse"></span>{t('global.damageUsage')}</h4>
                    {renderBulkCheckbox('damage')}
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-4">
                        <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.initDmg')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.InitialDamage ?? ""} onChange={e => updateGlobal('InitialDamage', parseFloat(e.target.value))} /></div>
                        <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.rndDmg')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.RandomDamage ?? ""} onChange={e => updateGlobal('RandomDamage', parseFloat(e.target.value))} /></div>
                    </div>
                    <div className="space-y-4">
                        <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.initUsg')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.InitialUsage ?? ""} onChange={e => updateGlobal('InitialUsage', parseFloat(e.target.value))} /></div>
                        <div><label className="text-xs text-gray-500 mb-1 block font-bold uppercase">{t('global.rndUsg')}</label><input type="number" step="any" min="0" className={getInputClass()} value={data.RandomUsage ?? ""} onChange={e => updateGlobal('RandomUsage', parseFloat(e.target.value))} /></div>
                    </div>
                </div>
            </div>

            {/* Post Spawn Actions */}
            <div className={`bg-scum-800/40 p-6 rounded-2xl border transition-all ${isBulkMode && selectedGroups?.has('actions') ? 'border-emerald-500 ring-1 ring-emerald-500/30 bg-scum-800/60' : 'border-emerald-500/50'}`}>
                <div className="flex justify-between items-center border-b border-scum-700/50 pb-2 mb-4">
                    <h4 className="text-xs font-bold text-emerald-400 uppercase tracking-wider flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>{t('global.actions')}</h4>
                    <div className="flex items-center gap-3">
                        {!isBulkMode && <button onClick={() => addItem('PostSpawnActions')} className="text-[10px] text-emerald-400 hover:text-white flex items-center gap-1 hover:bg-emerald-500/20 px-2 py-1 rounded transition-colors"><PlusIcon /> {t('btn.add')}</button>}
                        {renderBulkCheckbox('actions')}
                    </div>
                </div>
                <div className="space-y-3">
                    {(data.PostSpawnActions || []).map((action, idx) => (
                        <div key={idx} className="bg-scum-900/30 p-2 rounded-lg border border-white/5 group flex flex-col gap-2">
                            <div className="flex gap-2 items-center">
                                <div className="flex-1">
                                    <select 
                                        className={`${getInputClass()} text-xs bg-transparent border-none`} 
                                        value={action} 
                                        onChange={(e) => updateStringItem('PostSpawnActions', idx, e.target.value)}
                                        disabled={isBulkMode}
                                    >
                                        {Object.keys(POST_SPAWN_ACTIONS).map(key => (
                                            <option key={key} value={key}>{t(`action_option.${key}`) || key}</option>
                                        ))}
                                    </select>
                                </div>
                                {!isBulkMode && <button onClick={() => deleteItem('PostSpawnActions', idx)} className="p-2 text-gray-600 hover:text-red-400 hover:bg-red-500/10 rounded transition-colors"><TrashIcon /></button>}
                            </div>
                            <div className="text-[10px] text-gray-500 italic px-1 whitespace-pre-wrap leading-relaxed border-t border-white/5 pt-1 mt-1">
                                {t(`action.${action}`) || POST_SPAWN_ACTIONS[action]}
                            </div>
                        </div>
                    ))}
                    {(!data.PostSpawnActions || data.PostSpawnActions.length === 0) && (
                        <div className="text-center py-4 text-xs text-gray-600 italic border border-dashed border-gray-700/50 rounded-lg">{t('common.emptyList')}</div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { ItemInput } from '../ItemInput';
import { TrashIcon, CheckCircleIcon } from '../Icons';
import { useI18n } from '../../i18n';
import { getItemTranslation, hasTranslation } from '../../utils/itemTranslator';

interface FixedItemsSectionProps {
    fixedItems: any[];
    isBulkMode: boolean;
    selectedIndices: Set<number>;
    onSelect: (index: number) => void;
    handleContainerDrop: (e: React.DragEvent, section: any) => void;
    deleteFixedItem: (index: number) => void;
    updateFixedItem: (index: number, field: 'Id' | 'Quantity', value: string | number) => void;
    filterList: (list: any[]) => { item: any; originalIndex: number }[];
    getInputClass: (key?: string) => string;
}

export const FixedItemsSection: React.FC<FixedItemsSectionProps> = ({
    fixedItems,
    isBulkMode,
    selectedIndices,
    onSelect,
    handleContainerDrop,
    deleteFixedItem,
    updateFixedItem,
    filterList,
    getInputClass
}) => {
    const { t } = useI18n();

    return (
        <div className="space-y-3 pb-20" onDragOver={(e) => e.preventDefault()} onDrop={(e) => handleContainerDrop(e, 'FixedItems')}>
            {filterList(fixedItems).map(({ item, originalIndex: idx }) => {
                const isSelected = selectedIndices.has(idx);
                const hasTrans = hasTranslation(item.Id || "");
                const translation = hasTrans ? getItemTranslation(item.Id || "") : null;

                return (
                <div 
                    key={idx} 
                    className={`
                        relative p-2 pl-4 rounded-lg flex items-center gap-4 border transition-all duration-200 focus-within:z-50
                        ${isSelected ? 'bg-scum-800/80 border-emerald-500/50 ring-1 ring-emerald-500/30' : 'bg-scum-800/30 border-transparent hover:bg-scum-800/60'}
                    `}
                >
                    {isBulkMode ? (
                        <div 
                            className={`w-5 h-5 rounded border cursor-pointer flex items-center justify-center shrink-0 transition-colors ${isSelected ? 'bg-emerald-500 border-emerald-500' : 'border-gray-600 hover:border-gray-400'}`}
                            onClick={() => onSelect(idx)}
                        >
                            {isSelected && <CheckCircleIcon className="w-3.5 h-3.5 text-black" />}
                        </div>
                    ) : (
                        <div className="text-[10px] font-mono text-gray-600 w-6 opacity-50 shrink-0">#{idx + 1}</div>
                    )}

                    <div className="flex-1 grid grid-cols-1 md:grid-cols-12 gap-4 items-center">
                        <div className="md:col-span-8 relative flex flex-col gap-1">
                            {hasTrans && (
                                <div className="text-xs font-bold text-sky-300 ml-1 drop-shadow-sm">{translation}</div>
                            )}
                            <ItemInput 
                                className={`${getInputClass(`fixed_${idx}_id`)} bg-transparent border-none h-8 font-mono text-xs ${hasTrans ? 'text-gray-500' : 'text-gray-200 font-bold'}`} 
                                value={item.Id || ""} 
                                onChange={(val) => updateFixedItem(idx, 'Id', val)} 
                                placeholder={t('editor.itemIdPlaceholder')} 
                            />
                        </div>
                        <div className="md:col-span-4 flex items-center gap-2">
                            <label className="text-[10px] text-gray-500 font-bold uppercase">{t('editor.qtyAbbr')}</label>
                            <input type="number" min="1" className={`${getInputClass()} text-xs py-1 h-8 shadow-sm font-bold text-emerald-300`} value={item.Quantity} onChange={(e) => updateFixedItem(idx, 'Quantity', parseInt(e.target.value) || 1)} />
                        </div>
                    </div>
                    <button onClick={() => deleteFixedItem(idx)} className="p-2 text-gray-600 hover:text-scum-danger"><TrashIcon /></button>
                </div>
            )})}
        </div>
    );
};
